sp_widget.client_script:
api.controller = function($scope, $interval, $timeout, spUtil) {
    /* Fun on PDI - Leaderboard: live for the projector.
     * Refreshes the moment a Team Session or the Puzzle changes (record watch),
     * with a 5-second poll as a safety net (it also ends the game when time runs out). */
    var c = this;
    var REFRESH_MS = 5000;

    c.board = c.data.board || {};
    c.clock = c.data.clock || {};
    c.clockText = '';
    var endAt = 0;
    var busy = false;

    sync();
    var poll = c.data.allowed ? $interval(refresh, REFRESH_MS) : null;

    var soon = null;
    function refreshSoon() {
        if (soon) $timeout.cancel(soon);
        soon = $timeout(refresh, 300); // several records change at once on End game
    }
    if (c.data.allowed) {
        spUtil.recordWatch($scope, 'x_1802710_fun_on_0_team_session', 'statusISNOTEMPTY', refreshSoon);
        spUtil.recordWatch($scope, 'x_1802710_fun_on_0_puzzle', 'active=true', refreshSoon);
    }
    var tick = $interval(updateClock, 1000);

    function refresh() {
        if (busy) return;
        busy = true;
        c.server.get({ action: 'refresh' }).then(function(r) {
            busy = false;
            c.board = r.data.board || c.board;
            c.clock = r.data.clock || c.clock;
            sync();
        }, function() { busy = false; });
    }

    function sync() {
        endAt = c.clock && c.clock.state == 'running' && c.clock.remainingSeconds !== null
            ? Date.now() + c.clock.remainingSeconds * 1000 : 0;
        updateClock();
    }

    function updateClock() {
        if (!endAt) { c.clockText = ''; return; }
        var sec = Math.max(0, Math.ceil((endAt - Date.now()) / 1000));
        var m = Math.floor(sec / 60), s = sec % 60;
        c.clockText = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
    }

    c.rowClass = function(r) {
        if (!r.rank) return 'is-pending';
        if (c.clock.state != 'ended') return '';   // top 3 highlighted only after the game ends
        return { 1: 'is-first', 2: 'is-second', 3: 'is-third' }[r.rank] || '';
    };

    c.statusLabel = function(r) {
        return { 'In progress': 'Playing' }[r.status] || r.status;
    };

    c.statusKey = function(r) {
        return r.status == 'Submitted' ? 'done' : (r.status == 'In progress' ? 'progress' : 'notstarted');
    };

    $scope.$on('$destroy', function() {
        if (poll) $interval.cancel(poll);
        $interval.cancel(tick);
    });
};

sp_widget.css:
/* Fun on PDI - Leaderboard, sized for a projector (BCE Global Tech palette) */
.lb {
  --brand: #00549a;
  --brand-dark: #003778;
  --ink: #1b2733;
  --muted: #5b6878;
  --line: #d5dee8;
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  color: var(--ink);
}
.lb-empty { margin: 40px auto; max-width: 520px; padding: 24px; border: 2px solid var(--brand); border-radius: 8px; }
.lb-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  flex-wrap: wrap;
  padding-bottom: 16px;
  border-bottom: 4px solid var(--brand);
  margin-bottom: 20px;
}
.lb-kicker { margin: 0 0 4px; font-weight: 800; color: var(--brand); letter-spacing: 0.02em; font-size: 26px; line-height: 1.1; }
.lb-head h1 { margin: 4px 0 0; font-size: 48px; font-weight: 800; color: var(--brand-dark); line-height: 1; }
.lb-sub { margin: 8px 0 0; color: var(--muted); font-size: 16px; }
.lb-clock {
  text-align: right;
  font-size: 52px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--brand-dark);
  line-height: 1;
}
.lb-clock span { display: block; font-size: 14px; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; }
.lb-clock.is-up { color: #b3261e; }
.lb-clock.is-idle { font-size: 30px; }
.lb-clock.is-final { color: #00549a; }

.lb-table { width: 100%; border-collapse: separate; border-spacing: 0 8px; font-size: 22px; }
.lb-table th {
  text-align: left;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  padding: 0 16px;
}
.lb-table td { padding: 14px 16px; background: #fff; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.lb-table td:first-child { border-left: 1px solid var(--line); border-radius: 8px 0 0 8px; }
.lb-table td:last-child { border-right: 1px solid var(--line); border-radius: 0 8px 8px 0; }
.lb-rank { font-weight: 800; width: 80px; color: var(--brand); }
.lb-team { font-weight: 800; }
.lb-points { font-weight: 800; }

/* new submissions slide in */
.lb-table tbody tr { animation: lb-in 0.4s ease-out; }
@keyframes lb-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .lb-table tbody tr { animation: none; } }

/* top 3, only once the game has ended */
.lb-table tr.is-first td { background: #00549a; color: #fff; border-color: #00549a; font-size: 26px; padding-top: 20px; padding-bottom: 20px; }
.lb-table tr.is-first .lb-rank { color: #fff; }
.lb-table tr.is-second td { background: #d3e5f7; border-color: #b7d3ee; }
.lb-table tr.is-third td { background: #e9f2fb; border-color: #cfe1f3; }
.lb-table tr.is-pending td { color: var(--muted); }

.lb-status { display: inline-block; padding: 3px 12px; border-radius: 14px; font-size: 15px; font-weight: 700; background: #e3f4ea; color: #167a4e; }
.lb-status.is-progress { background: #fff3dc; color: #a86400; }
.lb-status.is-notstarted { background: #eef1f4; color: var(--muted); }
.is-first .lb-status { background: #fff; color: #00549a; }
.lb-none { text-align: center; color: var(--muted); }
.lb-foot { margin-top: 16px; color: var(--muted); font-size: 14px; text-align: center; }

@media (max-width: 760px) {
  .lb-head h1 { font-size: 34px; }
  .lb-clock { font-size: 36px; }
  .lb-table { font-size: 16px; }
}

sp_widget.script:
(function() {
    /* Fun on PDI - Leaderboard (server script). Game masters only. */
    data.allowed = gs.hasRole('x_1802710_fun_on_0.game_master');
    if (!data.allowed) return;

    var svc = new FunCrosswordService();
    svc.autoSubmitExpired();             // keeps the board current even if nobody's browser is open
    data.board = svc.getLeaderboard();
    var clock = svc.getGameClock();
    data.clock = clock.ok ? clock.puzzle : {};
})();
